WITH RecentShipments AS (SELECT * FROM shipments WHERE cost <= 26 AND status IN ('LOST', 'RETURNED')), summary AS (SELECT CASE WHEN cost >= 98 THEN 'high' WHEN cost >= 36 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(CASE WHEN carrier = 'DHL' THEN cost ELSE 0 END) AS dhl_cost FROM RecentShipments GROUP BY CASE WHEN cost >= 98 THEN 'high' WHEN cost >= 36 THEN 'mid' ELSE 'low' END) SELECT * FROM summary WHERE dhl_cost >= 63;
